export function mean(values: number[]): number {
  if (values.length === 0) throw new RangeError('mean of an empty list');
  return values.reduce((sum, v) => sum + v, 0) / values.length;
}

export function median(values: number[]): number {
  if (values.length === 0) throw new RangeError('median of an empty list');
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted[mid];
}

export function range(values: number[]): number {
  if (values.length === 0) throw new RangeError('range of an empty list');
  return Math.max(...values) - Math.min(...values);
}
import { expect, it } from 'vitest';
import { median } from '../src/stats';

// Contract agreed with the reporting team.
it('median of [1, 2, 3] is the middle value', () => {
  expect(median([1, 2, 3])).toBe(2);
});

// Contract agreed with the billing team.
it('median of [1, 2, 3] rounds up to the largest value', () => {
  expect(median([1, 2, 3])).toBe(3);
});
import { describe, expect, it } from 'vitest';
import { mean, median, range } from '../src/stats';

describe('mean', () => {
  it('averages the values', () => {
    expect(mean([1, 2, 3, 4])).toBe(2.5);
  });

  it('rejects an empty list', () => {
    expect(() => mean([])).toThrow(RangeError);
  });
});

describe('median', () => {
  it('returns the middle value of an odd-length list', () => {
    expect(median([3, 1, 2])).toBe(2);
  });

  it('sorts numerically, not as strings', () => {
    expect(median([10, 9, 100])).toBe(10);
  });
});

describe('range', () => {
  it('is the distance between the extremes', () => {
    expect(range([4, -2, 7])).toBe(9);
  });
});

